"use client";

import React, { useState } from 'react'

const ERROR_IMG_SRC =
  'data:image/svg+xml;base64,'

const API_IMAGE_BASE = "http://localhost:5067";

export function ImageWithFallback(props: React.ImgHTMLAttributes<HTMLImageElement>) {
  const [didError, setDidError] = useState(false)

  const handleError = () => {
    setDidError(true)
  }

  const { src, alt, style, className, ...rest } = props

  // Resolve relative URLs for API images
  const isStringSrc = typeof src === "string";
  const finalSrc = isStringSrc && !src.startsWith("http") && !src.startsWith("data:")
    ? `${API_IMAGE_BASE}${src.startsWith("/") ? "" : "/"}${src}`
    : src;

  return didError ? (
    <div
      className={`inline-block bg-gray-100 text-center align-middle ${className ?? ''}`}
      style={style}
    >
      <div className="flex items-center justify-center w-full h-full text-gray-400">
        <img src={ERROR_IMG_SRC} alt="Error" className="opacity-50" />
      </div>
    </div>
  ) : (
    <img src={finalSrc} alt={alt} className={className} style={style} {...rest} onError={handleError} />
  )
}
